/* Decision history is career-owned JSON. No entries are fabricated for old saves. */
const DECISION_TYPES=['Trade','Signing','Release','Hire','Fire','TicketChange','StrategyShift'];
let officeTab='overview',decisionUI={season:'all',type:'all',player:'',impact:'all',sort:'date',timeline:true};
function decisionState(){return state.decisions||(state.decisions={entries:[],agentTrust:50,fanSentiment:0,chemistry:0,payroll:{amount:payroll(),capSpace:salaryCap()-payroll()}})}
const decisionClamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function decisionDate(){return scheduleDate(Math.min(state.day+1,seasonLength())).toISOString().slice(0,10)}
function addDecision(input){
 if(!DECISION_TYPES.includes(input.type))throw Error('Unknown decision type');
 const log=decisionState(),o=ownerFor(team()),effects=input.immediateOutcome||{},id=input.id||('decision-'+state.year+'-'+Date.now()+'-'+log.entries.length);
 if(log.entries.some(d=>d.id===id))return id;
 const d={id,date:input.date||decisionDate(),season:state.year,teamRecord:team().w+'-'+team().l,ownerMood:o.patience,type:input.type,description:String(input.description||'').slice(0,1000),reasoning:String(input.reasoning||'Not recorded — add your reasoning.').slice(0,2000),immediateOutcome:{fanReaction:decisionClamp(Math.round(effects.fanReaction||0),-10,10),ownerReaction:decisionClamp(Math.round(effects.ownerReaction||0),-10,10),chemistryChange:decisionClamp(Math.round(effects.chemistryChange||0),-10,10),capChange:effects.capChange||'+0.0M'},longTermOutcome:{updated:false,notes:''},players:input.players||[],baseline:{wins:team().w,losses:team().l},grade:null,teamKey:team().key};
 log.entries.push(d);o.patience=decisionClamp(o.patience+d.immediateOutcome.ownerReaction,0,100);if(o.patience===0)o.fired=true;
 log.fanSentiment=decisionClamp(log.fanSentiment+d.immediateOutcome.fanReaction,-20,20);log.chemistry=decisionClamp(log.chemistry+d.immediateOutcome.chemistryChange,-15,15);
 log.payroll={amount:payroll(),capSpace:salaryCap()-payroll()};return id;
}
function updateLongTermOutcome(id,notes){const d=decisionState().entries.find(d=>d.id===id);if(!d)return false;d.longTermOutcome={updated:true,notes:String(notes).slice(0,3000)};return true}
function evaluateDecisionLog(force=false){const log=decisionState();for(const d of log.entries){if(d.longTermOutcome.updated||d.season!==state.year||d.teamKey!==team().key||controlledTeamId()<0)continue;const games=team().w+team().l-d.baseline.wins-d.baseline.losses;if(games<20&&!force)continue;if(games<=0)continue;const wins=team().w-d.baseline.wins,pct=wins/games,grade=pct>=.7?'A':pct>=.55?'B':pct>=.4?'C':pct>=.25?'D':'F';d.grade=grade;updateLongTermOutcome(d.id,'Context estimate: team went '+wins+'-'+(games-wins)+' after this move. Other decisions, opponents and injuries also affect results.');log.agentTrust=decisionClamp(log.agentTrust+({A:2,B:1,C:0,D:-1,F:-2}[grade]),0,100)}}
function filterDecisionLog(c=decisionUI){return decisionState().entries.filter(d=>(c.season==='all'||String(d.season)===String(c.season))&&(c.type==='all'||d.type===c.type)&&(!c.player||d.players.some(p=>p.name.toLowerCase().includes(c.player.toLowerCase())))&&(c.impact==='all'||(c.impact==='positive'?decisionImpact(d)>0:c.impact==='negative'?decisionImpact(d)<0:decisionImpact(d)===0)))}
function decisionImpact(d){const e=d.immediateOutcome;return e.fanReaction+e.ownerReaction+e.chemistryChange}
function sortDecisionLog(c=decisionUI,entries=filterDecisionLog(c)){return [...entries].sort((a,b)=>c.sort==='date'?b.date.localeCompare(a.date)||b.id.localeCompare(a.id):b.immediateOutcome[c.sort]-a.immediateOutcome[c.sort])}
function setOfficeTab(tab){officeTab=tab;render()}
function decisionFilter(key,value){decisionUI[key]=value;render()}
async function saveDecisionReason(id,value){const d=decisionState().entries.find(d=>d.id===id);if(!d)return;const old=d.reasoning;d.reasoning=value.trim().slice(0,2000);if(!await save()){d.reasoning=old;return toast('Could not save reasoning.')}toast('Reasoning saved')}
function decisionWhatIf(id){const d=decisionState().entries.find(d=>d.id===id);if(!d)return;titleModal('What If? · Comparison hook','<p>This is a comparison snapshot, not a resimulation.</p><p>Without this move, the immediate cap-space difference would be the inverse of '+escapeHTML(d.immediateOutcome.capChange)+'.</p><p>Alternate game outcomes are not available without a saved pre-decision roster and random seed. Your career is unchanged.</p>')}
function decisionLogView(){const log=decisionState(),rows=sortDecisionLog(),years=[...new Set(log.entries.map(d=>d.season))].sort((a,b)=>b-a);const select=(key,label,options)=>'<label>'+label+'<select onchange="decisionFilter(\''+key+'\',this.value)">'+options.map(([v,n])=>'<option value="'+v+'" '+(String(decisionUI[key])===String(v)?'selected':'')+'>'+n+'</option>').join('')+'</select></label>';
 return '<section class="gm-panel"><div class="gm-panel-heading"><h2>Decision Log</h2><span>Agent trust '+log.agentTrust+'/100</span></div><div class="decision-filters">'+select('season','Season',[['all','GM Career Timeline'],...years.map(y=>[y,y])])+select('type','Type',[['all','All decisions'],...DECISION_TYPES.map(t=>[t,t])])+select('impact','Impact',[['all','All'],['positive','Positive'],['negative','Negative'],['neutral','Neutral']])+select('sort','Sort by',[['date','Date · newest first'],['fanReaction','Fan reaction'],['ownerReaction','Owner reaction']])+'<label>Player<input type="search" value="'+escapeHTML(decisionUI.player)+'" placeholder="Player name" onchange="decisionFilter(\'player\',this.value)"></label></div><p class="office-helper">'+rows.length+' decisions · Reactions are game-model estimates. Grades reflect subsequent team results, not isolated causation.</p><div class="decision-timeline">'+(rows.length?rows.map(d=>'<details class="decision-card"><summary><span>'+d.date+' · '+d.season+' · '+d.type+'</span><strong>'+escapeHTML(d.description)+'</strong><small>'+d.teamRecord+' · Owner '+d.ownerMood+'/100'+(d.grade?' · Grade '+d.grade:' · Awaiting review')+'</small></summary><div class="decision-body"><label>GM reasoning<textarea maxlength="2000" id="reason-'+d.id+'">'+escapeHTML(d.reasoning)+'</textarea></label><button onclick="saveDecisionReason(\''+d.id+'\',document.getElementById(\'reason-'+d.id+'\').value)">Save reasoning</button><dl>'+Object.entries(d.immediateOutcome).map(([k,v])=>'<div><dt>'+({fanReaction:'Fan reaction',ownerReaction:'Owner reaction',chemistryChange:'Chemistry',capChange:'Cap space change'}[k])+'</dt><dd>'+v+'</dd></div>').join('')+'</dl><p>'+escapeHTML(d.longTermOutcome.notes||'Review after 20 team games or at season end.')+'</p><button onclick="decisionWhatIf(\''+d.id+'\')">What If? comparison</button></div></details>').join(''):'<p>No decisions match these filters. Completed moves will appear here.</p>')+'</div></section>';
}
const officeBeforeDecisions=gmOfficePage;gmOfficePage=function(){return '<div class="standings-view-toggle" role="group" aria-label="GM Office sections"><button onclick="setOfficeTab(\'overview\')" aria-pressed="'+(officeTab==='overview')+'">Office Overview</button><button onclick="setOfficeTab(\'decisions\')" aria-pressed="'+(officeTab==='decisions')+'">Decision Log</button></div>'+(officeTab==='decisions'?decisionLogView():officeBeforeDecisions())};
const businessBeforeDecisions=ownerBusinessProjection;ownerBusinessProjection=function(club,plan){const p=businessBeforeDecisions(club,plan),sentiment=club.id===controlledTeamId()?(state.decisions?.fanSentiment||0):0;return {...p,attendance:typeof createGameAtmosphere==='function'?p.attendance:decisionClamp(p.attendance+sentiment*.001,0,1),merchPerHome:p.merchPerHome*(1+sentiment*.005)}};
const chemistryBeforeDecisions=teamChemistry;teamChemistry=function(club){const c=chemistryBeforeDecisions(club),change=club.id===controlledTeamId()?(state.decisions?.chemistry||0):0;return {...c,score:decisionClamp(c.score+change,0,100),modifier:c.modifier+change/10}};
const quoteBeforeDecisions=freeAgentQuote;freeAgentQuote=function(p,club=team()){const trust=club.id===controlledTeamId()?(state.decisions?.agentTrust??50):50;return Math.round(quoteBeforeDecisions(p,club)*(1+(50-trust)*.001)*10)/10};
const negotiateBeforeDecisions=negotiationStatus;negotiationStatus=function(p){const n=negotiateBeforeDecisions(p),trust=state.decisions?.agentTrust??50;return {...n,refuses:n.refuses||(trust<20&&n.score<60),premium:Math.max(0,n.premium+(50-trust)*.001)}};
const ownerDayBeforeDecisions=ownerDay;ownerDay=function(){ownerDayBeforeDecisions();if(state.decisions)evaluateDecisionLog()};
const newSeasonBeforeDecisions=newSeason;newSeason=function(){if(state.champion!==null&&ownerCanManage()&&state.decisions)evaluateDecisionLog(true);return newSeasonBeforeDecisions()};
function decisionSnapshot(){return {roster:team().roster.map(p=>({id:p.id,name:p.name,ovr:p.ovr,salary:p.salary,term:p.contractThrough})),payroll:payroll(),ticket:ownerFor(team()).plan.ticketPrice,strategy:JSON.stringify([state.pace,state.focus,team().rotationPlan,team().roster.map(p=>[p.id,p.rotationMinutes])])}}
function completedGMDecision(type,before){const after=decisionSnapshot(),out=before.roster.filter(p=>!after.roster.some(q=>q.id===p.id)),incoming=after.roster.filter(p=>!before.roster.some(q=>q.id===p.id)),extended=after.roster.filter(p=>before.roster.some(q=>q.id===p.id&&(q.term!==p.term||q.salary!==p.salary)));let description='',players=[...out,...incoming,...extended],fan=0;
 if(type==='Trade'&&out.length&&incoming.length){description='Traded '+out.map(p=>p.name).join(', ')+' for '+incoming.map(p=>p.name).join(', ');fan=Math.sign(incoming[0].ovr-out[0].ovr)*2}
 if(type==='Signing'&&(incoming.length||extended.length)){description=(incoming.length?'Signed ':'Extended ')+(incoming.length?incoming:extended).map(p=>p.name).join(', ');fan=1}
 if(type==='Release'&&out.length){description='Released '+out.map(p=>p.name).join(', ');fan=out.some(p=>p.ovr>=80)?-3:-1}
 if(type==='TicketChange'&&before.ticket!==after.ticket){description='Changed ticket price from $'+before.ticket+' to $'+after.ticket;fan=after.ticket>before.ticket?-1:1}
 if(type==='StrategyShift'&&before.strategy!==after.strategy)description='Updated game strategy or applied rotation';
 if(!description)return;const delta=before.payroll-after.payroll;addDecision({type,description,players:players.map(p=>({id:p.id,name:p.name})),immediateOutcome:{fanReaction:fan,ownerReaction:type==='Trade'||type==='Signing'||type==='Release'?(ownerFor(team()).type==='penny'?Math.sign(delta):Math.sign(fan)):0,chemistryChange:type==='Trade'?-1:0,capChange:(delta>=0?'+':'')+delta.toFixed(1)+'M'}});save().then(ok=>{if(!ok)toast('Decision recorded in memory but could not be saved. Try saving again.');});render();
}
function installDecisionActionHooks(){for(const [name,type] of [['trade','Trade'],['sign','Signing'],['releasePlayer','Release'],['confirmContractExtension','Signing'],['ownerTicketPrice','TicketChange'],['setStrategy','StrategyShift'],['applyRotationPlan','StrategyShift']]){const original=window[name];if(typeof original!=='function')continue;window[name]=function(...args){const before=decisionSnapshot(),career=state,result=original.apply(this,args);if(result&&typeof result.then==='function')return result.then(value=>{if(state===career)completedGMDecision(type,before);return value});if(state===career)completedGMDecision(type,before);return result}}}
function readDecisionState(raw,bad){if(raw===undefined)return undefined;if(!raw||!Array.isArray(raw.entries)||raw.entries.length>100000)bad('invalid decision log');for(const k of ['agentTrust','fanSentiment','chemistry'])if(!Number.isFinite(raw[k]))bad('invalid decision modifiers');const ids=new Set();for(const d of raw.entries){if(!d||typeof d.id!=='string'||!/^[-a-zA-Z0-9]+$/.test(d.id)||ids.has(d.id)||!DECISION_TYPES.includes(d.type)||!Number.isInteger(d.season)||typeof d.teamKey!=='string'||d.teamKey.length>80||d.season<1900||d.season>10000||typeof d.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||!Number.isFinite(Date.parse(d.date))||typeof d.description!=='string'||d.description.length>1000||typeof d.reasoning!=='string'||d.reasoning.length>2000||typeof d.teamRecord!=='string'||!/^\d+-\d+$/.test(d.teamRecord)||!Number.isInteger(d.ownerMood)||d.ownerMood<0||d.ownerMood>100||!d.immediateOutcome||!d.longTermOutcome||typeof d.longTermOutcome.updated!=='boolean'||typeof d.longTermOutcome.notes!=='string'||d.longTermOutcome.notes.length>3000||!d.baseline||!Number.isInteger(d.baseline.wins)||!Number.isInteger(d.baseline.losses)||!Array.isArray(d.players)||d.players.some(p=>!Number.isInteger(p.id)||typeof p.name!=='string'||p.name.length>80)||![null,'A','B','C','D','F'].includes(d.grade))bad('invalid decision entry');for(const k of ['fanReaction','ownerReaction','chemistryChange'])if(!Number.isInteger(d.immediateOutcome[k])||Math.abs(d.immediateOutcome[k])>10)bad('invalid decision reaction');if(!/^[+-]\d+\.\d+M$/.test(d.immediateOutcome.capChange))bad('invalid decision cap delta');ids.add(d.id)}return {...raw,agentTrust:decisionClamp(raw.agentTrust,0,100),fanSentiment:decisionClamp(raw.fanSentiment,-20,20),chemistry:decisionClamp(raw.chemistry,-15,15)}}
